"""The files the web build and its e2e specs take from the seed are generated by the engine, and
are not hand-edited: if the rules change, these fail until `python -m dgate.readiness.export <root>`
is run again and the result committed.
"""

from __future__ import annotations

import json
from pathlib import Path

from dgate.readiness import export

ROOT = Path(__file__).resolve().parents[3]


def test_the_generated_web_files_are_up_to_date():
    assert export.main([str(ROOT), "--check"]) == 0


def test_the_e2e_fixtures_state_the_verdicts_of_the_two_test_profiles():
    def verdicts(key):
        body = json.loads((ROOT / "web" / "e2e" / "fixtures" / f"assess-{key}.json").read_text(encoding="utf-8"))
        return {a["programme"]: a["verdict"] for a in body["assessments"]}
    # the free PIC and NCAGE are "obtain first" (WP-33, D3), not blocks. EDIP the Programme: blocked for the Ukrainian
    # company (Ukraine is not an associated country there), "obtain" for the Spanish one (only the PIC is missing).
    # The EDF is "conditional" for the Ukrainian company: the EU-Ukraine association agreement is not confirmed (V2-B2).
    expected = {"EDF": "conditional", "EDIP": "blocked", "EDIP-USI": "obtain", "SAFE": "eligible", "NATO-SUPPLY": "obtain"}
    assert verdicts("ua") == expected
    # the Spanish company also needs a Ukrainian applicant or partner for the Ukraine Support Instrument (WP-42 R1)
    # and, since WP-64, the Spanish defence supplier route. WP-73: it handles classified information and answered "We do not hold it" for
    # the HSEM in step 4, and a conditional rule binds where it applies (Ley 24/2011 art. 21.2), so the route is blocked by ES-HSEM
    assert verdicts("es") == {**expected, "EDF": "obtain", "EDIP": "obtain", "EDIP-USI": "conditional", "ES-MOD": "blocked"}
    es = json.loads((ROOT / "web" / "e2e" / "fixtures" / "assess-es.json").read_text(encoding="utf-8"))
    assert next(a for a in es["assessments"] if a["programme"] == "ES-MOD")["blocking"] == ["ES-HSEM"]
    ua = json.loads((ROOT / "web" / "e2e" / "fixtures" / "assess-ua.json").read_text(encoding="utf-8"))
    edip = next(a for a in ua["assessments"] if a["programme"] == "EDIP")
    assert edip["blocking"] == ["EDIP-ESTABLISH", "EDIP-EXEC-MGMT"]      # Ukraine is not an associated country of the Programme
    assert edip["toObtain"] == ["EDIP-PIC"]
    pic = json.loads((ROOT / "web" / "e2e" / "fixtures" / "assess-ua-pic.json").read_text(encoding="utf-8"))
    assert {a["programme"]: a["verdict"] for a in pic["assessments"]} == {
        "EDF": "conditional", "EDIP": "blocked", "EDIP-USI": "eligible", "SAFE": "eligible", "NATO-SUPPLY": "obtain"}
    assert "REQ-PIC" not in [s["code"] for s in pic["roadmap"]["steps"]]
    # WP-53 (T4): "Not applicable to us" for the PIC is neither "met" nor a step: the rule is left out of the programmes' cards
    na = json.loads((ROOT / "web" / "e2e" / "fixtures" / "assess-ua-pic-na.json").read_text(encoding="utf-8"))
    for programme, code in (("EDF", "EDF-PIC"), ("EDIP", "EDIP-PIC"), ("EDIP-USI", "USI-PIC")):
        rule = next(r for a in na["assessments"] if a["programme"] == programme for r in a["rules"] if r["rule"] == code)
        assert rule["outcome"] == "not_applicable" and "You have a PIC" not in rule["reason"]
    assert "REQ-PIC" not in [s["code"] for s in na["roadmap"]["steps"]]
    es = json.loads((ROOT / "web" / "e2e" / "fixtures" / "assess-es.json").read_text(encoding="utf-8"))
    edip_es = next(a for a in es["assessments"] if a["programme"] == "EDIP")
    assert edip_es["blocking"] == [] and edip_es["toObtain"] == ["EDIP-PIC"]


def test_the_request_fixtures_are_what_the_api_accepts():
    from dgate.readiness.api import AssessIn

    for key in ("ua", "es", "ua-pic", "ua-pic-na", "es-auto"):
        body = json.loads((ROOT / "web" / "e2e" / "fixtures" / f"request-{key}.json").read_text(encoding="utf-8"))
        AssessIn.model_validate(body)
